#include <string.h>

void compress_string(const char *src, char *dest)
{
    if (!src || !dest) {
        *dest = '\0';
        return;
    }

    const char *run_start = src;
    char *d = dest;

    while (*run_start) {
        char ch = *run_start;
        int count = 0;

        while (*run_start == ch) {
            count++;
            run_start++;
        }

        *d++ = ch;
        if (count > 9) {
            char buf[16];
            int n = snprintf(buf, sizeof(buf), "%d", count);
            memcpy(d, buf, n);
            d += n;
        } else {
            *d++ = '0' + count;
        }
    }

    *d = '\0';
}

